<?php $types = App\Services\RestaurantService::TYPES; $st = ['open' => ['warning text-dark', 'En cours'], 'billed' => ['info', 'Addition'], 'paid' => ['success', 'Payée'], 'cancelled' => ['secondary', 'Annulée']]; ?>
<div class="card mb-3"><div class="card-body py-2"><form class="row g-2 align-items-end" method="get"><?= App\Core\View::partial('partials/period', compact('from', 'to')) ?>
  <div class="col-auto"><label class="form-label small mb-0">Statut</label><select name="status" class="form-select form-select-sm"><option value="">Tous</option><?php foreach ($st as $k => [, $l]): ?><option value="<?= $k ?>" <?= ($_GET['status'] ?? '') === $k ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
  <div class="col-auto"><button class="btn btn-sm btn-primary">Filtrer</button></div><div class="col-auto ms-auto"><a href="<?= e(url('/restaurant')) ?>" class="btn btn-sm btn-success"><i class="bi bi-grid-3x3"></i> Plan de salle</a></div></form></div></div>
<div class="card"><div class="table-responsive"><table class="table table-sm table-hover mb-0"><thead><tr><th>N°</th><th>Ouverture</th><th>Type</th><th>Table / client</th><th>Serveur</th><th class="num">Couv.</th><th class="num">Total</th><th>Statut</th></tr></thead><tbody>
<?php foreach ($p['rows'] as $o): ?><tr><td><a href="<?= e(url('/restaurant/orders/' . $o['id'])) ?>"><?= e($o['number']) ?></a></td><td><?= e(fdate($o['opened_at'])) ?></td><td><?= e($types[$o['type']]) ?></td><td><?= e($o['table_name'] ?? $o['customer_name'] ?? '') ?></td><td><?= e($o['waiter']) ?></td><td class="num"><?= (int) $o['covers'] ?></td><td class="num"><?= money($o['total']) ?></td><td><span class="badge bg-<?= $st[$o['status']][0] ?>"><?= e($st[$o['status']][1]) ?></span></td></tr><?php endforeach; ?>
<?php if (!$p['rows']): ?><tr><td colspan="8" class="text-center text-secondary py-4">Aucune commande.</td></tr><?php endif; ?>
</tbody></table></div></div>
